struct LargeObject {
    int data[1024];
    // Ensure large size makes copies inefficient
};

// Efficient parameter passing: no copy occurs
// Safety: Immutability guaranteed during function execution
void process_large(const LargeObject& obj) {
    long sum = 0;
    for (int i = 0; i < 1024; ++i) {
        sum += obj.data[i];
    }
    // obj.data[0] = 5; // Compiler Error: Cannot modify const object
}

// Usage: LargeObject instance; process_large(instance);
